  'Every tally counts two ways: all users, and verified users. Verified means an adult Chicago resident of a ward - nothing about party or voter registration. Use the toggle to switch views.': 'हर गिनती दो तरह से होती है: सभी उपयोगकर्ता, और सत्यापित उपयोगकर्ता। सत्यापित का मतलब है शिकागो के किसी वार्ड का वयस्क निवासी - पार्टी या मतदाता पंजीकरण से इसका कोई लेना-देना नहीं। दृश्य बदलने के लिए टॉगल का उपयोग करें।',
  'Verification is handled by Didit, an independent identity service. Your documents go to Didit, never to us - all we ever receive is a yes/no and your ward.': 'सत्यापन Didit करता है, जो एक स्वतंत्र पहचान सेवा है। आपके दस्तावेज़ Didit के पास जाते हैं, हमारे पास कभी नहीं - हमें सिर्फ़ हाँ/ना और आपका वार्ड मिलता है।',
  'Answers, replies, and credits, as they land.': 'जवाब, प्रतिक्रियाएँ और क्रेडिट, जैसे ही आते हैं।',
  'Sign in and this is where responses to your questions and comments arrive.': 'साइन इन करें, और आपके सवालों और टिप्पणियों के जवाब यहाँ आएँगे।',
  'Sign in': 'साइन इन करें',
  'Nothing yet. Ask a question or join an argument and the responses land here.': 'अभी कुछ नहीं। कोई सवाल पूछें या किसी चर्चा में शामिल हों, और जवाब यहाँ आएँगे।',
  'Mark all {n} read': 'सभी {n} को पढ़ा हुआ मार्क करें',
  'Could not update': 'अपडेट नहीं हो सका',
  'Sign in to vote on concerns, join ward votes, and hold officials to account.': 'मुद्दों पर वोट देने, वार्ड के मतदानों में हिस्सा लेने और अधिकारियों से जवाब माँगने के लिए साइन इन करें।',
  'Sign in or create account': 'साइन इन करें या खाता बनाएँ',
  'Could not update name': 'नाम अपडेट नहीं हो सका',
