  'You’re verified as a resident of the {ward}. Your votes count in the verified tallies.': 'आप {ward} के निवासी के रूप में सत्यापित हैं। आपके वोट सत्यापित गिनती में गिने जाते हैं।',
  'You’re verified as a Chicago resident. Your votes count in the verified tallies.': 'आप शिकागो के निवासी के रूप में सत्यापित हैं। आपके वोट सत्यापित गिनती में गिने जाते हैं।',
  'Verify once to unlock your ward tab and make your votes count in the verified tallies. A third-party service (Didit) checks your ID. We only ever receive a yes/no and your ward. No documents, no address, nothing else.': 'अपना वार्ड टैब खोलने और अपने वोटों को सत्यापित गिनती में गिनवाने के लिए एक बार सत्यापन करें। एक बाहरी सेवा (Didit) आपकी ID जाँचती है। हमें सिर्फ़ हाँ/ना और आपका वार्ड मिलता है। कोई दस्तावेज़ नहीं, कोई पता नहीं, और कुछ नहीं।',
  'Verify my identity': 'मेरी पहचान सत्यापित करें',
