  'Verify to unlock your home ward': 'अपना होम वार्ड खोलने के लिए सत्यापन करें',
  'Anyone can vote and comment here; raising a ward concern takes a verified resident.': 'यहाँ कोई भी वोट और टिप्पणी कर सकता है; वार्ड का मुद्दा उठाने के लिए सत्यापित निवासी होना ज़रूरी है।',
  'Anyone can vote and comment here; ward posting unlocks once your verification includes your ward.': 'यहाँ कोई भी वोट और टिप्पणी कर सकता है; जब आपके सत्यापन में आपका वार्ड शामिल होगा, तब वार्ड में पोस्ट करना खुलेगा।',
  'Anyone can vote and comment here; you raise ward concerns in your home ward, the {ward}.': 'यहाँ कोई भी वोट और टिप्पणी कर सकता है; वार्ड के मुद्दे आप अपने होम वार्ड, {ward}, में उठाते हैं।',
