  'How verification works': 'सत्यापन कैसे काम करता है',
  'You verify your ID and Chicago address with Didit, a third-party identity service. Your documents go to them, never to us.': 'आप अपनी ID और शिकागो का पता Didit से सत्यापित करते हैं, जो एक बाहरी पहचान सेवा है। आपके दस्तावेज़ उनके पास जाते हैं, हमारे पास कभी नहीं।',
  'All we ever save: a verified yes/no, the ward you live in, and a unique identifier that stops one person from verifying twice.': 'हम बस इतना ही सहेजते हैं: सत्यापन का हाँ/ना, आप किस वार्ड में रहते हैं, और एक विशिष्ट पहचानकर्ता जो एक व्यक्ति को दो बार सत्यापन करने से रोकता है।',
  'No name, no address, no document. Your display name stays anonymous, even once verified.': 'कोई नाम नहीं, कोई पता नहीं, कोई दस्तावेज़ नहीं। सत्यापन के बाद भी आपका दिखने वाला नाम गुमनाम रहता है।',
  'Start verification with Didit': 'Didit के साथ सत्यापन शुरू करें',
  'ama': 'AMA',
  'Ongoing ask-me-anythings with Chicago’s elected officials, each graded two ways: approval from their constituents, and whether they actually answer questions.': 'शिकागो के निर्वाचित अधिकारियों के साथ लगातार चलने वाले AMA (कुछ भी पूछें), हर एक को दो तरह से ग्रेड मिलता है: उनके क्षेत्र के लोगों की स्वीकृति, और क्या वे सच में सवालों के जवाब देते हैं।',
  'No officials on the platform yet.': 'प्लेटफ़ॉर्म पर अभी कोई अधिकारी नहीं है।',
