  'Could not ask': 'सवाल नहीं पूछा जा सका',
  'Do you approve of the job {name} is doing?': 'क्या आप {name} के काम से संतुष्ट हैं?',
  'Ask anything. The community judges whether the question was answered sufficiently.': 'कुछ भी पूछें। समुदाय तय करता है कि सवाल का जवाब ठीक से दिया गया या नहीं।',
  'Ask {name} anything…': '{name} से कुछ भी पूछें…',
