  'On the platform - this official answers here': 'प्लेटफ़ॉर्म पर - यह अधिकारी यहाँ जवाब देते हैं',
  'Not on the platform yet. This profile is public record; {name} can claim it any time, and unanswered questions stay pending until they do.': 'अभी प्लेटफ़ॉर्म पर नहीं हैं। यह प्रोफ़ाइल सार्वजनिक रिकॉर्ड है; {name} इसे कभी भी क्लेम कर सकते हैं, और तब तक बिना जवाब वाले सवाल लंबित रहते हैं।',
  'Approval': 'स्वीकृति',
