  'straight answers given': 'सीधे जवाब दिए',
  'How answers are graded': 'जवाबों को ग्रेड कैसे मिलता है',
  'Every response counts as answered until the community judges it a dodge. Each question is weighted by the verified people who joined it, so ignoring a question fifty people want answered costs far more than ignoring one nobody backed. Unanswered questions get a week of grace before they count as ignored.': 'हर जवाब तब तक जवाब माना जाता है जब तक समुदाय उसे टालमटोल न ठहरा दे। हर सवाल का वज़न उससे जुड़े सत्यापित लोगों के हिसाब से होता है, इसलिए जिस सवाल का जवाब पचास लोग चाहते हैं उसे अनदेखा करना, ऐसे सवाल को अनदेखा करने से कहीं ज़्यादा भारी पड़ता है जिसका किसी ने समर्थन नहीं किया। बिना जवाब वाले सवालों को अनदेखा गिने जाने से पहले एक हफ़्ते की मोहलत मिलती है।',
