  'Link a photo hosted on your own site or campaign page - direct democracy displays it but never stores the image.': 'अपनी साइट या अभियान पेज पर होस्ट की गई फ़ोटो का लिंक दें - direct democracy उसे दिखाता है लेकिन तस्वीर कभी सहेजता नहीं।',
