  'Tap one to see votes and comments': 'वोट और टिप्पणियाँ देखने के लिए किसी एक पर टैप करें',
  'You haven\'t raised a concern yet.': 'आपने अभी तक कोई मुद्दा नहीं उठाया है।',
  'My AMA questions': 'मेरे AMA सवाल',
  'Tap one to see the official\'s page': 'अधिकारी का पेज देखने के लिए किसी एक पर टैप करें',
  'You haven\'t asked an official anything yet.': 'आपने अभी तक किसी अधिकारी से कुछ नहीं पूछा है।',
  'Community reviewing': 'समुदाय समीक्षा कर रहा है',
  'direct democracy is built to know as little about you as possible while still keeping the vote honest.': 'direct democracy इस तरह बना है कि वोट ईमानदार रहे और फिर भी आपके बारे में कम से कम जानकारी रखी जाए।',
  'What we store': 'हम क्या सहेजते हैं',
  'Your email and password hash (for signing in) - never shown to anyone.': 'आपका ईमेल और पासवर्ड हैश (साइन इन के लिए) - किसी को कभी नहीं दिखाया जाता।',
  'A display name you choose. It\'s a pseudonym; your real name is never shown, even after verification.': 'आपका चुना हुआ दिखने वाला नाम। यह एक उपनाम है; आपका असली नाम कभी नहीं दिखाया जाता, सत्यापन के बाद भी नहीं।',
  'Your ballots, comments, questions, and judgments - the content you post.': 'आपके वोट, टिप्पणियाँ, सवाल और फ़ैसले - वह सामग्री जो आप पोस्ट करते हैं।',
  'If you verify: a yes/no verified flag, your ward, and a unique identifier used to block duplicate accounts. Nothing else, and it is deleted with your account.': 'अगर आप सत्यापन करते हैं: सत्यापित होने का हाँ/ना निशान, आपका वार्ड, और डुप्लिकेट खातों को रोकने वाला एक विशिष्ट पहचानकर्ता। इसके अलावा कुछ नहीं, और आपका खाता हटाने पर यह भी हट जाता है।',
  'Participation counters (votes cast, concerns raised) that power your milestones.': 'भागीदारी की गिनती (डाले गए वोट, उठाए गए मुद्दे) जिनसे आपकी उपलब्धियाँ बनती हैं।',
  'What we never see': 'हम क्या कभी नहीं देखते',
  'Your identity documents. Verification is performed by Didit, a third-party service; documents go to them, and we receive only the verdict.': 'आपके पहचान दस्तावेज़। सत्यापन Didit करता है, जो एक बाहरी सेवा है; दस्तावेज़ उनके पास जाते हैं, और हमें सिर्फ़ नतीजा मिलता है।',
  'Your address. It is used only at the moment you verify, to find your ward, and is never saved.': 'आपका पता। इसका उपयोग सिर्फ़ सत्यापन के समय आपका वार्ड खोजने के लिए होता है, और इसे कभी सहेजा नहीं जाता।',
  'If you pay for a verification: which one you bought, when, and the store’s transaction number. Your payment details stay with Apple or Google.': 'अगर आप सत्यापन के लिए भुगतान करते हैं: आपने कौन सा खरीदा, कब, और स्टोर का ट्रांज़ैक्शन नंबर। आपकी भुगतान जानकारी Apple या Google के पास ही रहती है।',
  'Who can see what': 'कौन क्या देख सकता है',
  'Your profile is readable only by you. Content you post carries your display name and a verified badge - nothing more.': 'आपकी प्रोफ़ाइल सिर्फ़ आप पढ़ सकते हैं। आपकी पोस्ट की गई सामग्री पर आपका दिखने वाला नाम और सत्यापित बैज होता है - इससे ज़्यादा कुछ नहीं।',
  'Your individual ballots and judgments are readable only by you; everyone else sees only aggregate tallies.': 'आपके अलग-अलग वोट और फ़ैसले सिर्फ़ आप पढ़ सकते हैं; बाकी सब सिर्फ़ कुल गिनती देखते हैं।',
  'Reports you file are visible only to the platform operators.': 'आपकी भेजी गई रिपोर्ट सिर्फ़ प्लेटफ़ॉर्म चलाने वाले देख सकते हैं।',
  'Your controls': 'आपके नियंत्रण',
  'Change your display name any time.': 'अपना दिखने वाला नाम कभी भी बदलें।',
  'Retract any vote while voting is open, withdraw your concerns and unanswered questions, delete your comments. Once a poll closes its result is a public record and ballots are final.': 'वोटिंग खुली रहने तक कोई भी वोट वापस लें, अपने मुद्दे और बिना जवाब वाले सवाल वापस लें, अपनी टिप्पणियाँ हटाएँ। पोल बंद होने के बाद उसका नतीजा सार्वजनिक रिकॉर्ड होता है और वोट अंतिम होते हैं।',
  'Block any user to hide their content from your account.': 'किसी भी उपयोगकर्ता को ब्लॉक करें ताकि उसकी सामग्री आपके खाते से छिप जाए।',
  'Delete your account any time from Settings: your sign-in, profile, verification status, and standing approvals of officials are removed. Anything you posted is re-attributed to [deleted], and votes you cast remain counted in the tallies.': 'सेटिंग्स से कभी भी अपना खाता हटाएँ: आपका साइन-इन, प्रोफ़ाइल, सत्यापन की स्थिति, और अधिकारियों को दी गई आपकी मौजूदा स्वीकृतियाँ हटा दी जाती हैं। आपने जो भी पोस्ट किया वह [deleted] के नाम हो जाता है, और आपके डाले गए वोट गिनती में बने रहते हैं।',
