  'Permanently removes your sign-in, profile, verification status, and standing approvals of officials. Anything you posted stays on the record but is re-attributed to [deleted], and votes you cast remain counted. This cannot be undone.': 'आपका साइन-इन, प्रोफ़ाइल, सत्यापन की स्थिति, और अधिकारियों को दी गई मौजूदा स्वीकृतियाँ हमेशा के लिए हटा देता है। आपने जो भी पोस्ट किया वह रिकॉर्ड पर रहता है लेकिन [deleted] के नाम हो जाता है, और आपके डाले गए वोट गिने जाते रहते हैं। इसे पहले जैसा नहीं किया जा सकता।',
