  'This permanently removes your sign-in, profile, verification, and standing approvals. Posts stay on the record as [deleted] and cast ballots remain counted. It cannot be undone.': 'इससे आपका साइन-इन, प्रोफ़ाइल, सत्यापन और मौजूदा स्वीकृतियाँ हमेशा के लिए हट जाती हैं। पोस्ट [deleted] के रूप में रिकॉर्ड पर रहती हैं और डाले गए वोट गिने जाते रहते हैं। इसे पहले जैसा नहीं किया जा सकता।',
