  'Verify a new address': 'नया पता सत्यापित करें',
  'Moved within Chicago? Verify your new address and your ward moves with you. If your ID shows the new address, your ID is enough. If it doesn’t, add a utility bill or bank statement from the last 3 months. You can do this once every 3 months.': 'शिकागो के अंदर ही घर बदला है? अपना नया पता सत्यापित करें और आपका वार्ड भी आपके साथ बदल जाएगा। अगर आपकी ID पर नया पता है, तो सिर्फ़ ID काफ़ी है। अगर नहीं, तो पिछले 3 महीनों का कोई यूटिलिटी बिल या बैंक स्टेटमेंट जोड़ें। आप ऐसा हर 3 महीने में एक बार कर सकते हैं।',
