  'Raise concerns, vote on ward polls, and rate your alderman.': 'मुद्दे उठाएँ, वार्ड के पोल में वोट दें, और अपने एल्डरमैन को रेटिंग दें।',
  'Verified residents also count in the verified tallies.': 'सत्यापित निवासी सत्यापित गिनती में भी गिने जाते हैं।',
  'Take part in your ward: verify your residency with your ID, or set your home ward without one.': 'अपने वार्ड में हिस्सा लें: अपनी ID से अपना निवास सत्यापित करें, या बिना ID के अपना होम वार्ड चुनें।',
  'Your home ward is the {ward}, set without verification. Verify your residency to make your votes count in the verified tallies; verifying places you in the ward on your ID.': 'आपका होम वार्ड {ward} है, जिसे बिना सत्यापन के चुना गया है। अपने वोटों को सत्यापित गिनती में गिनवाने के लिए अपना निवास सत्यापित करें; सत्यापन आपको उस वार्ड में रखता है जो आपकी ID पर है।',
  'Your home ward is the {ward}.': 'आपका होम वार्ड {ward} है।',
  'Home ward set': 'होम वार्ड चुन लिया गया',
