  'Rating officials takes a home ward.': 'अधिकारियों को रेटिंग देने के लिए होम वार्ड ज़रूरी है।',
  'Ward polls are for residents of the ward.': 'वार्ड के पोल उस वार्ड के निवासियों के लिए हैं।',
  'Set your home ward': 'अपना होम वार्ड चुनें',
  'No ID needed to set a home ward. Verified residents also count in the verified tallies.': 'होम वार्ड चुनने के लिए ID की ज़रूरत नहीं। सत्यापित निवासी सत्यापित गिनती में भी गिने जाते हैं।',
  'Pay {price} and start': '{price} भुगतान करें और शुरू करें',
