  'Couldn’t load the price. Check your connection and try again.': 'कीमत लोड नहीं हो सकी। अपना कनेक्शन जाँचें और फिर कोशिश करें।',
  'Already paid. This attempt is covered.': 'भुगतान पहले ही हो चुका है। यह कोशिश कवर है।',
  'Paying for verification works in the iPhone and Android apps.': 'सत्यापन के लिए भुगतान iPhone और Android ऐप में होता है।',
