  'Your candidate profile isn’t set up yet.': 'आपकी उम्मीदवार प्रोफ़ाइल अभी सेट नहीं हुई है।',
  'From “ask every candidate”, most joined first. Voters see every candidate’s answer side by side.': '“हर उम्मीदवार से पूछें” से, सबसे ज़्यादा लोगों वाले पहले। मतदाता हर उम्मीदवार का जवाब साथ-साथ देखते हैं।',
