  'Also a city service problem? Report it to 311': 'क्या यह शहर की सेवा से जुड़ी समस्या भी है? 311 पर रिपोर्ट करें',
  'More help voting': 'वोट देने में और मदद',
  'Voting with a disability: an accessible mail ballot you mark online and print, curbside voting (request it by 5 pm the day before election day), and help at 312-269-7976.': 'विकलांगता के साथ वोट देना: एक सुलभ डाक मतपत्र जिसे आप ऑनलाइन भरकर प्रिंट करते हैं, कर्बसाइड वोटिंग (चुनाव से एक दिन पहले शाम 5 बजे तक अनुरोध करें), और 312-269-7976 पर मदद।',
  'Help in your language: every voting machine has ballots in 12 languages, many sites have bilingual officials, and you may bring someone to interpret.': 'आपकी भाषा में मदद: हर वोटिंग मशीन पर 12 भाषाओं में मतपत्र हैं, कई केंद्रों पर दो भाषाएँ बोलने वाले कर्मचारी हैं, और आप अनुवाद के लिए किसी को साथ ला सकते हैं।',
  'Get a mail ballot for every future election by joining the permanent vote by mail roster.': 'स्थायी डाक मतदान सूची में शामिल होकर आगे के हर चुनाव के लिए डाक मतपत्र पाएँ।',
  'Under 18? You can pre-register online at 16.': '18 से कम उम्र है? आप 16 साल की उम्र में ऑनलाइन पहले से पंजीकरण कर सकते हैं।',
  'Work the polls: election judges are paid $170 to $230 for the day. High school juniors and seniors can serve too.': 'मतदान केंद्र पर काम करें: चुनाव जजों को एक दिन के $170 से $230 मिलते हैं। हाई स्कूल के आखिरी दो सालों के छात्र भी सेवा कर सकते हैं।',
